        }
        * { box-sizing: border-box; }
        [hidden] { display: none !important; }
        body {
          margin: 0;
          font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
          font-size: 1.0625rem;
          line-height: 1.5;
          color: var(--ink);
          background: var(--paper);
        }
        main { max-width: 40rem; margin: 0 auto; padding: 1rem 1rem 2rem; }
        h1 { font-family: var(--title); font-weight: 800; font-size: 1.6rem; line-height: 1.2; margin: 0.5rem 0 0.25rem; }
        h2 { font-family: var(--title); font-weight: 800; font-size: 1.15rem; margin: 0 0 0.5rem; }
        p { margin: 0 0 0.75rem; }
        .intro { color: var(--muted); }
        .carte {
          background: var(--card);
          border-radius: 20px;
          box-shadow: 0 4px 0 var(--line);
          padding: 1rem 1.1rem;
          margin: 1rem 0;
        }
        .aide { color: var(--muted); font-size: 0.95rem; }
        .depot {
          display: block;
          border: 2px dashed var(--brand);
          border-radius: 14px;
          background: var(--brand-pale);
          padding: 1rem;
          text-align: center;
          cursor: pointer;
        }
        .depot.survol { background: #f9cfdd; }
        .depot strong { color: var(--brand-dark); }
        .depot input { position: absolute; opacity: 0; width: 1px; height: 1px; }
        .depot:focus-within { outline: 3px solid var(--brand); outline-offset: 2px; }
        .choix { display: flex; gap: 0.75rem; align-items: flex-start; padding: 0.5rem 0; min-height: 44px; cursor: pointer; }
        .choix input { width: 1.4rem; height: 1.4rem; margin: 0.1rem 0 0; accent-color: var(--brand); flex: none; }
        .choix small { display: block; color: var(--muted); }
        button, .bouton {
          display: inline-block;
          font: inherit;
          font-weight: 700;
          min-height: 48px;
          padding: 0.7rem 1.5rem;
          border: 0;
          border-radius: 999px;
          background: var(--brand);
          color: #fff;
          box-shadow: 0 4px 0 var(--brand-shadow);
          cursor: pointer;
          text-decoration: none;
        }
        button:active, .bouton:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--brand-shadow); }
        button:disabled { opacity: 0.5; cursor: default; transform: none; box-shadow: 0 4px 0 var(--brand-shadow); }
        button:focus-visible, .bouton:focus-visible { outline: 3px solid var(--brand); outline-offset: 3px; }
        .secondaire { background: var(--brand-pale); color: var(--brand-dark); box-shadow: none; }
        .secondaire:active { box-shadow: none; }
        .message { border-radius: 14px; padding: 0.75rem 1rem; margin: 0.75rem 0 0; }
        .erreur { background: var(--brand-pale); color: var(--brand-shadow); }
        .info { background: var(--info); }
        .succes { background: var(--success); color: var(--success-ink); }
        .barre { height: 12px; border-radius: 999px; background: var(--line); overflow: hidden; margin: 0.5rem 0; }
        .barre span { display: block; height: 100%; width: 0; background: var(--brand); transition: width 0.3s; }
        .barre.indefinie span { width: 30%; animation: va-et-vient 1.4s ease-in-out infinite alternate; }
        @keyframes va-et-vient { from { margin-left: 0; } to { margin-left: 70%; } }
        details { margin-top: 0.5rem; font-size: 0.9rem; }
        pre { white-space: pre-wrap; word-break: break-word; font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 0.8rem; }
        footer { color: var(--muted); font-size: 0.9rem; }
        a { color: var(--brand-dark); }
        a.bouton { color: #fff; }
      </style>
      </head>
      <body>
      <main>
        <h1>WordPress vers Markdown</h1>
        <p class="intro">Transformez les articles et les pages d'un site WordPress en fichiers texte Markdown, avec leurs images, pour les garder ou les mettre dans un autre site.</p>

        <p id="outil" class="message info" hidden></p>

        <form id="formulaire" class="carte">
          <h2>1. Votre fichier d'export WordPress</h2>
          <p class="aide">Dans votre WordPress, ouvrez le menu <strong>Outils → Exporter</strong>, choisissez « Tout le contenu », puis « Télécharger le fichier d'export » : vous obtenez un fichier qui se termine par <strong>.xml</strong>.</p>
          <label class="depot" id="depot">
            <input type="file" id="fichier" accept=".xml,application/xml,text/xml">
            <strong id="nom-fichier">Choisir le fichier .xml</strong><br>
            <span class="aide" id="taille-max">ou le déposer ici</span>
          </label>

          <h2 style="margin-top:1.25rem">2. Réglages</h2>
          <label class="choix"><input type="checkbox" id="images" checked>
            <span>Télécharger les images<small>Celles des articles et des pages, prises sur votre site WordPress d'origine, qui doit être en ligne. Plus long.</small></span></label>
          <label class="choix"><input type="checkbox" id="annees">
            <span>Ranger les articles par année et par mois<small>Par exemple un dossier 2024, puis 05 pour mai.</small></span></label>
          <label class="choix"><input type="checkbox" id="date">
            <span>Mettre la date au début du nom de chaque article<small>Par exemple 2024-05-17-mon-article.</small></span></label>

          <p style="margin:1rem 0 0"><button type="submit" id="lancer">Convertir</button></p>
          <p id="erreur-envoi" class="message erreur" role="alert" hidden></p>
        </form>

        <section id="suivi" class="carte" hidden aria-live="polite">
          <h2 id="suivi-titre">Conversion en cours…</h2>
          <div id="barre" class="barre indefinie"><span></span></div>
          <p id="suivi-texte"></p>
          <div id="pret" hidden>
            <p class="message succes" id="pret-texte"></p>
            <p id="images-ratees" class="message info" hidden></p>
            <p style="margin-top:1rem"><a class="bouton" id="telecharger" href="#" download="wordpress-markdown.zip">Télécharger le fichier .zip</a></p>
          </div>
          <div id="echec" hidden>
            <p class="message erreur" id="echec-texte" role="alert"></p>
            <details id="echec-details" hidden><summary>Détails</summary><pre id="echec-pre"></pre></details>
          </div>
          <p id="recommencer-ligne" hidden style="margin-top:1rem"><button type="button" class="secondaire" id="recommencer">Convertir un autre fichier</button></p>
        </section>

        <footer>
          <p>Votre fichier reste sur ce Raspberry Pi : rien n'est envoyé ailleurs, sauf les demandes d'images à votre site WordPress d'origine. Les fichiers sont effacés du Pi peu après le téléchargement, et au plus tard une heure après la conversion.</p>
          <p>Conversion faite par <a href="https://github.com/lonekorean/wordpress-export-to-markdown">wordpress-export-to-markdown</a> (licence MIT), dans pi-appliance.</p>
        </footer>
      </main>
      <script>
      "use strict";
      (function () {
        var TAILLE_MAX = 40 * 1024 * 1024;
        // Adresses relatives : la page marche aussi sous un chemin (/<service>/).
        var base = location.pathname.slice(-1) === "/" ? "" : location.pathname.split("/").pop() + "/";
        var champ = document.getElementById("fichier");
        var depot = document.getElementById("depot");
        var formulaire = document.getElementById("formulaire");
        var bouton = document.getElementById("lancer");
        var suivi = document.getElementById("suivi");
        var fichier = null;
        var identifiant = "";
        var minuterie = 0;

        function el(id) { return document.getElementById(id); }
        function montrer(id, oui) { el(id).hidden = !oui; }
        function mo(octets) {
          if (octets < 1024 * 1024) { return Math.max(1, Math.round(octets / 1024)) + " Ko"; }
          return (octets / 1024 / 1024).toLocaleString("fr-FR", { maximumFractionDigits: 1 }) + " Mo";
        }
        function memoriser(valeur) {
          try { if (valeur) { sessionStorage.setItem("conversion", valeur); } else { sessionStorage.removeItem("conversion"); } } catch (e) { /* navigateur sans stockage */ }
        }
        function relire() {
          try { return sessionStorage.getItem("conversion") || ""; } catch (e) { return ""; }
        }

        el("taille-max").textContent = "ou le déposer ici (" + mo(TAILLE_MAX) + " au plus)";

        function choisir(f) {
          fichier = f || null;
          montrer("erreur-envoi", false);
          el("nom-fichier").textContent = fichier ? fichier.name + " (" + mo(fichier.size) + ")" : "Choisir le fichier .xml";
        }
        champ.addEventListener("change", function () { choisir(champ.files[0]); });
        ["dragenter", "dragover"].forEach(function (nom) {
          depot.addEventListener(nom, function (e) { e.preventDefault(); depot.classList.add("survol"); });
        });
        ["dragleave", "drop"].forEach(function (nom) {
          depot.addEventListener(nom, function () { depot.classList.remove("survol"); });
        });
        depot.addEventListener("drop", function (e) {
          e.preventDefault();
          if (e.dataTransfer && e.dataTransfer.files.length) { choisir(e.dataTransfer.files[0]); }
        });

        function erreurEnvoi(texte) {
          el("erreur-envoi").textContent = texte;
          montrer("erreur-envoi", true);
          bouton.disabled = false;
        }

        formulaire.addEventListener("submit", function (e) {
          e.preventDefault();
          if (!fichier) { erreurEnvoi("Choisissez d'abord le fichier d'export WordPress (.xml)."); return; }
          if (fichier.name.slice(-4).toLowerCase() !== ".xml") {
            erreurEnvoi("Ce fichier ne se termine pas par .xml : ce n'est pas un export WordPress. Dans WordPress, ouvrez Outils → Exporter.");
            return;
          }
          if (fichier.size > TAILLE_MAX) { erreurEnvoi("Ce fichier est trop gros : " + mo(TAILLE_MAX) + " au plus."); return; }
          var fuseau = "UTC";
          try { fuseau = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"; } catch (x) { /* fuseau inconnu */ }
          var requete = "convertir?images=" + (el("images").checked ? 1 : 0) + "&annees=" + (el("annees").checked ? 1 : 0) +
            "&date=" + (el("date").checked ? 1 : 0) + "&fuseau=" + encodeURIComponent(fuseau);
          bouton.disabled = true;
          montrer("erreur-envoi", false);
          var xhr = new XMLHttpRequest();
          xhr.open("POST", base + requete);
          xhr.setRequestHeader("Content-Type", "application/xml");
          xhr.upload.onprogress = function (p) {
            if (p.lengthComputable) { bouton.textContent = "Envoi du fichier : " + Math.round(100 * p.loaded / p.total) + " %"; }
          };
          xhr.onloadend = function () {
            bouton.textContent = "Convertir";
            var reponse = {};
            try { reponse = JSON.parse(xhr.responseText); } catch (x) { /* réponse vide */ }
            if (xhr.status === 202 && reponse.id) {
              identifiant = reponse.id;
              memoriser(identifiant);
              commencerSuivi();
              return;
            }
            if (xhr.status === 0) { erreurEnvoi("Le Pi ne répond pas : vérifiez la connexion et réessayez."); return; }
            if (xhr.status === 401 || xhr.status === 403) { erreurEnvoi("Votre connexion a expiré : rechargez la page et reconnectez-vous."); return; }
            erreurEnvoi(reponse.erreur || "L'envoi n'a pas abouti (erreur " + xhr.status + "). Réessayez.");
          };
          xhr.send(fichier);
        });

        function commencerSuivi() {
          formulaire.hidden = true;
          suivi.hidden = false;
          montrer("pret", false);
          montrer("echec", false);
          montrer("recommencer-ligne", false);
          el("suivi-titre").textContent = "Conversion en cours…";
          el("suivi-texte").textContent = "Lecture du fichier…";
          barre(-1);
          relever();
        }

        function barre(part) {
          var b = el("barre");
          b.hidden = part === null;
          b.classList.toggle("indefinie", part < 0);
          b.firstElementChild.style.width = part < 0 ? "" : Math.round(part * 100) + "%";
        }

        function compte(n, un, plusieurs) { return n + " " + (n > 1 ? plusieurs : un); }

        function relever() {
          clearTimeout(minuterie);
          fetch(base + "etat?id=" + encodeURIComponent(identifiant), { cache: "no-store", credentials: "same-origin" })
            .then(function (r) { if (!r.ok) { throw new Error(String(r.status)); } return r.json(); })
            .then(afficher)
            .catch(function () {
              el("suivi-texte").textContent = "Le Pi ne répond pas pour le moment, nouvel essai…";
              minuterie = setTimeout(relever, 3000);
            });
        }

        function afficher(etat) {
          var c = etat.conversion;
          if (!c) {
            memoriser("");
            finir("La conversion n'est plus sur le Pi (fichiers effacés au bout d'une heure, ou Pi redémarré). Relancez-la.", "");
            return;
          }
          var trouves = compte(c.articles, "article", "articles") + " et " + compte(c.pages, "page", "pages") + " trouvés";
          if (c.etape === "lecture" || c.etape === "envoi") {
            el("suivi-texte").textContent = "Lecture du fichier…";
            barre(-1);
          } else if (c.etape === "textes") {
            el("suivi-texte").textContent = trouves + ". Écriture des fichiers Markdown…";
            barre(-1);
          } else if (c.etape === "images") {
            el("suivi-texte").textContent = trouves + ". Téléchargement des images : " + c.images_faites + " sur " + c.images_total + "…";
            barre(c.images_total ? c.images_faites / c.images_total : -1);
          } else if (c.etape === "archive") {
            el("suivi-texte").textContent = trouves + ". Préparation du fichier .zip…";
            barre(-1);
          } else if (c.etape === "pret") {
            el("suivi-titre").textContent = "C'est prêt !";
            el("suivi-texte").textContent = "";
            barre(null);
            el("pret-texte").textContent = trouves + ". Le fichier .zip fait " + mo(c.taille) + ".";
            el("images-ratees").textContent = c.images_ratees ? compte(c.images_ratees, "image n'a", "images n'ont") +
              " pas pu être téléchargée" + (c.images_ratees > 1 ? "s" : "") + " depuis votre site d'origine (site hors ligne, image supprimée ou adresse changée) : la liste est dans le fichier images-manquantes.txt du .zip." : "";
            montrer("images-ratees", c.images_ratees > 0);
            el("telecharger").href = base + "telecharger?id=" + encodeURIComponent(identifiant);
            montrer("pret", true);
            montrer("recommencer-ligne", true);
            return;
          } else if (c.etape === "erreur") {
            memoriser("");
            finir(c.erreur, c.details);
            return;
          }
          minuterie = setTimeout(relever, 1000);
        }

        function finir(texte, details) {
          el("suivi-titre").textContent = "La conversion n'a pas abouti";
          el("suivi-texte").textContent = "";
          barre(null);
          el("echec-texte").textContent = texte;
          el("echec-pre").textContent = details || "";
          montrer("echec-details", Boolean(details));
          montrer("echec", true);
          montrer("recommencer-ligne", true);
        }

        el("telecharger").addEventListener("click", function () { memoriser(""); });

        el("recommencer").addEventListener("click", function () {
          clearTimeout(minuterie);
          identifiant = "";
          memoriser("");
          suivi.hidden = true;
          formulaire.hidden = false;
          bouton.disabled = false;
          champ.value = "";
          choisir(null);
        });

        // État de l'outil (premier démarrage) ; conversion reprise après un rechargement.
        function verifierOutil() {
          fetch(base + "etat", { cache: "no-store", credentials: "same-origin" })
            .then(function (r) { return r.json(); })
            .then(function (etat) {
              if (etat.taille_max) {
                TAILLE_MAX = etat.taille_max;
                el("taille-max").textContent = "ou le déposer ici (" + mo(TAILLE_MAX) + " au plus)";
              }
              el("outil").textContent = etat.outil_message || "";
              montrer("outil", !etat.outil_pret);
              if (!etat.outil_pret) { setTimeout(verifierOutil, 5000); }
            })
            .catch(function () { setTimeout(verifierOutil, 5000); });
        }
        verifierOutil();
        identifiant = relire();
        if (identifiant) { commencerSuivi(); }
      })();
      </script>
      </body>
      </html>
